INSERT INTO plant (code, slug, name, botanical_name, category_id, price, mrp, stock, image,
  rating, review_count, short_description, description, care_tip,
  pet_safety, difficulty, light_need, water_need, maintenance, growth_rate, mature_size,
  care_light, care_water, care_soil, care_humidity, care_temperature, care_feed, care_repot,
  is_featured, is_best_seller)
SELECT 'p01', 'aloe-vera', 'Aloe Vera', 'Aloe barbadensis', c.id,
  449, 599, 40, 'plants/aloe-vera.jpg',
  4.8, 312, 'A medicine cabinet in a pot — sculptural, sun-loving and famously hard to kill.', 'Aloe Vera stores water in its thick, ridged leaves, which is exactly why it forgives you for forgetting it. Snap a leaf and the clear gel inside soothes burns and dry skin. It wants bright light and gritty soil, and almost nothing else.', 'If the leaves turn flat and pale, it wants more light, not more water.',
  'toxic', 'Easy', 'high', 'low',
  'Low', 'Slow', '30–60 cm',
  'Bright, direct sun for 4–6 hours. A south or west windowsill is ideal.', 'Every 2–3 weeks. Let the soil dry out completely first — the commonest way to kill an aloe is kindness.', 'Free-draining cactus or succulent mix with added sand or perlite.', 'Ordinary room humidity. Dislikes damp, stagnant air.',
  '18–30 °C. Protect from anything below 10 °C.', 'A weak succulent feed twice through summer. Nothing in winter.', 'Every 2–3 years, or when offsets crowd the pot.',
  TRUE, TRUE
FROM category c WHERE c.slug = 'succulents';
INSERT INTO plant (code, slug, name, botanical_name, category_id, price, mrp, stock, image,
  rating, review_count, short_description, description, care_tip,
  pet_safety, difficulty, light_need, water_need, maintenance, growth_rate, mature_size,
  care_light, care_water, care_soil, care_humidity, care_temperature, care_feed, care_repot,
  is_featured, is_best_seller)
SELECT 'p02', 'snake-plant-cast-iron', 'Cast Iron Plant', 'Aspidistra elatior', c.id,
  699, 899, 25, 'plants/cast-iron-plant.jpg',
  4.9, 187, 'The plant that survives the hallway, the spare room and the long holiday.', 'Named for its constitution. The Cast Iron Plant tolerates deep shade, draughts, irregular watering and being ignored for a month — and still puts out glossy, deep green leaves. If you have killed everything else, start here.', 'Wipe the leaves monthly. Dust is the only thing that really slows it down.',
  'safe', 'Easy', 'low', 'low',
  'Very Low', 'Slow', '45–75 cm',
  'Low to moderate indirect light. Keep out of direct sun, which scorches the leaves.', 'Every 2–3 weeks, once the top 5 cm of soil is dry.', 'Any decent, well-draining potting mix.', 'Unfussy. Ordinary room humidity is fine.',
  '10–29 °C. Handles cold rooms better than most.', 'Balanced liquid feed once a month in spring and summer.', 'Rarely — every 3–4 years. It prefers being slightly pot-bound.',
  TRUE, FALSE
FROM category c WHERE c.slug = 'indoor-plants';
INSERT INTO plant (code, slug, name, botanical_name, category_id, price, mrp, stock, image,
  rating, review_count, short_description, description, care_tip,
  pet_safety, difficulty, light_need, water_need, maintenance, growth_rate, mature_size,
  care_light, care_water, care_soil, care_humidity, care_temperature, care_feed, care_repot,
  is_featured, is_best_seller)
SELECT 'p03', 'dumbcane', 'Dumbcane', 'Dieffenbachia seguine', c.id,
  599, 749, 18, 'plants/dumbcane.jpg',
  4.5, 94, 'Big, brushstroked cream-and-green leaves that fill a corner fast.', 'Dumbcane grows quickly into a bold, upright plant with dramatic variegation. It asks for warmth, steady moisture and no direct sun. Its sap is genuinely irritating, so it belongs high on a shelf if you have pets or small children.', 'Wear gloves when pruning — the sap irritates skin and mouth.',
  'toxic', 'Moderate', 'medium', 'medium',
  'Medium', 'Fast', '60–150 cm',
  'Bright indirect light. Direct sun bleaches the variegation.', 'Weekly. Keep lightly moist but never soggy.', 'Rich, peat-based mix that holds a little moisture.', 'Likes it above 50%. Group with other plants or mist occasionally.',
  '18–27 °C. Keep away from cold draughts.', 'Balanced feed every 3–4 weeks in spring and summer.', 'Every 2 years in spring.',
  FALSE, FALSE
FROM category c WHERE c.slug = 'indoor-plants';
INSERT INTO plant (code, slug, name, botanical_name, category_id, price, mrp, stock, image,
  rating, review_count, short_description, description, care_tip,
