  care_light, care_water, care_soil, care_humidity, care_temperature, care_feed, care_repot,
  is_featured, is_best_seller)
SELECT 'p04', 'friendship-plant', 'Friendship Plant', 'Pilea involucrata', c.id,
  399, 499, 32, 'plants/friendship-plant.jpg',
  4.7, 141, 'Quilted bronze leaves on a compact plant that begs to be shared.', 'So easy to propagate that it is traditionally passed between friends — hence the name. The deeply textured leaves look almost hammered. Perfect for a desk, a shelf or a small bathroom.', 'Pinch the growing tips to keep it bushy instead of leggy.',
  'safe', 'Easy', 'medium', 'medium',
  'Low', 'Moderate', '15–30 cm',
  'Bright indirect light. Tolerates a little shade.', 'Weekly. Keep evenly moist in summer, drier in winter.', 'Light, well-draining mix with some peat or coco coir.', 'Enjoys humidity — a bathroom or kitchen suits it well.',
  '16–27 °C.', 'Half-strength liquid feed monthly through the growing season.', 'Annually in spring; take cuttings at the same time.',
  TRUE, FALSE
FROM category c WHERE c.slug = 'indoor-plants';
