SELECT 'p05', 'grape-ivy', 'Grape Ivy', 'Cissus rhombifolia', c.id,
  549, 699, 22, 'plants/grape-ivy.jpg',
  4.6, 88, 'A graceful trailing vine for shelves, baskets and stair rails.', 'Grape Ivy climbs or cascades with equal enthusiasm, throwing out tendrils and glossy toothed leaflets. It is one of the few genuinely pet-safe trailing plants, and it copes with less light than most vines.', 'Give it a moss pole and it will climb; leave it high and it will spill.',
  'safe', 'Easy', 'medium', 'medium',
  'Low', 'Fast', 'Trails to 1.8 m',
  'Medium to bright indirect light. Avoid harsh direct sun.', 'Weekly. Let the top 3 cm dry between waterings.', 'Standard potting mix with good drainage.', 'Average to high. Mist in dry months.',
  '16–26 °C.', 'Monthly balanced feed from spring to early autumn.', 'Every 2 years, or top-dress a large hanging basket.',
  FALSE, FALSE
FROM category c WHERE c.slug = 'indoor-plants';
