SELECT 'p06', 'jade-plant', 'Jade Plant', 'Crassula ovata', c.id,
  499, 649, 45, 'plants/jade-plant.jpg',
  4.8, 264, 'A miniature tree of plump, coin-shaped leaves — the money plant of Vastu.', 'Jade thickens into a woody little trunk over years and can outlive its owner. Traditionally kept near an entrance to invite prosperity. It wants sun, sharp drainage and to be left thoroughly alone between waterings.', 'Wrinkled leaves mean thirst. Yellow, mushy leaves mean you overdid it.',
  'toxic', 'Easy', 'high', 'low',
  'Low', 'Slow', '30–90 cm',
  'At least 4 hours of bright light; some direct sun deepens the red leaf edges.', 'Every 2–3 weeks in summer, monthly in winter. Soak, then let it dry fully.', 'Gritty succulent mix. Drainage matters more than richness.', 'Low humidity preferred.',
  '18–30 °C. Keep above 10 °C.', 'Diluted succulent feed 2–3 times over summer.', 'Every 3 years. A snug pot keeps it compact and stable.',
  FALSE, TRUE
FROM category c WHERE c.slug = 'succulents';
