SELECT 'p07', 'lucky-bamboo', 'Lucky Bamboo', 'Dracaena sanderiana', c.id,
  349, 449, 60, 'plants/lucky-bamboo.jpg',
  4.6, 401, 'Grows in nothing but water and a handful of pebbles.', 'Not a bamboo at all, but a Dracaena — which is why it lives happily in a vase of water on a desk. Arrangements are counted deliberately: three stalks for happiness, five for wealth, eight for growth.', 'Use filtered or rested water. Fluoride in tap water browns the tips.',
  'toxic', 'Easy', 'low', 'high',
  'Very Low', 'Slow', '20–90 cm',
  'Indirect light only. Direct sun scorches and yellows the stalks.', 'Keep roots submerged in 5 cm of water; change it every 2 weeks.', 'Pebbles and water, or a well-draining mix if potted in soil.', 'Average room humidity.',
  '18–32 °C.', 'A single drop of liquid feed every couple of months — no more.', 'Move to a larger vase when the roots fill the base.',
  FALSE, TRUE
FROM category c WHERE c.slug = 'indoor-plants';
