SELECT 'p38', 'lavender', 'Lavender', 'Lavandula angustifolia', c.id,
  499, 649, 38, 'plants/lavender.jpg',
  4.6, 274, 'Scent, colour, and every bee within half a kilometre.', 'Silver foliage and purple spikes that perfume a balcony in the evening. Lavender wants exactly what most plants do not - poor gritty soil, full sun and very little water. Give it those and it thrives.', 'Contains linalool, which is mildly toxic to cats and dogs if eaten. Fine on a balcony, not on the floor indoors.',
  'caution', 'Moderate', 'high', 'low',
  'Low', 'Moderate', '40-80 cm',
  'Full sun, at least 6 hours.', 'Every 7-10 days. Overwatering is the usual cause of death.', 'Gritty, alkaline, sharply drained. Never rich or soggy.', 'Low. Good airflow prevents rot.',
  '15-30 C.', 'None needed. Feeding gives soft growth and fewer flowers.', 'Every 2 years, pruning by a third at the same time.',
  FALSE, FALSE
FROM category c WHERE c.slug = 'flowering-plants';
