SELECT 'p39', 'basil', 'Sweet Basil', 'Ocimum basilicum', c.id,
  199, 279, 80, 'plants/basil.jpg',
  4.8, 431, 'Pet safe, endlessly useful, and it grows faster than you can cook.', 'The most productive plant in this catalogue for the money. A single pot on a sunny sill supplies a kitchen all season, and the more you pick the bushier it gets. Completely safe around pets and children.', 'Harvest from the top, just above a leaf pair, and pinch out flowers. Flowering ruins the flavour.',
  'safe', 'Easy', 'high', 'high',
  'Low', 'Fast', '30-50 cm',
  'Full sun, 5-6 hours minimum.', 'Every 1-2 days. Basil wilts dramatically when thirsty, then recovers.', 'Rich, well-draining potting mix with compost.', 'Average.',
  '20-32 C. It dislikes anything below 12 C.', 'Light nitrogen feed fortnightly.', 'Grown as an annual - sow fresh each season.',
  FALSE, TRUE
FROM category c WHERE c.slug = 'outdoor-plants';
