  349, 449, 60, 'care/moisture-meter.jpg',
  4.6, 217, 'Settles the only argument that kills houseplants.', 'Push the probe to root depth and read it. Removes the guesswork that causes overwatering, which is the single commonest way a houseplant dies.', NULL,
  NULL, NULL, NULL, NULL,
  '—', '—', '—',
  NULL, NULL, NULL, NULL,
  NULL, NULL, NULL,
  FALSE, TRUE
FROM category c WHERE c.slug = 'plant-care';

